import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

// The client is generated by scripts/sync-role-model.mjs into every service, so
// these cases cover all copies.
vi.mock('dotenv/config', () => ({}));
vi.mock('../config', () => ({ config: { orgContextUrl: 'http://registry.test/' } }));

import {
  clearOrgContextCache,
  ORG_CONTEXT_TTL_MS,
  ORG_NOT_REGISTERED_TTL_MS,
  resolveOrgContext,
} from './org-context';

const ORG_A = 'org-a';
const ORG_B = 'org-b';
const TOKEN_A = 'eyJ.token-of-a-user-in-org-a.sig';
const TOKEN_B = 'eyJ.token-of-a-user-in-org-b.sig';
const contextA = { orgId: ORG_A, concessionId: 'conc-1', assemblyId: 'asm-a', scope: 'ASSEMBLY' };
const contextB = { orgId: ORG_B, concessionId: 'conc-1', assemblyId: 'asm-b', scope: 'ASSEMBLY' };

const fetchMock = vi.fn<typeof fetch>();

function reply(status: number, body?: unknown): Response {
  return new Response(body === undefined ? null : JSON.stringify(body), {
    status,
    headers: { 'content-type': 'application/json' },
  });
}

beforeEach(() => {
  clearOrgContextCache();
  fetchMock.mockReset();
  vi.stubGlobal('fetch', fetchMock);
  vi.useFakeTimers();
});

afterEach(() => {
  vi.useRealTimers();
  vi.unstubAllGlobals();
});

describe('resolveOrgContext', () => {
  it('asks /v1/org-context/me with the caller token and no org id in the URL', async () => {
    fetchMock.mockResolvedValueOnce(reply(200, contextA));

    await expect(resolveOrgContext(ORG_A, TOKEN_A)).resolves.toEqual(contextA);

    const [url, init] = fetchMock.mock.calls[0];
    expect(url).toBe('http://registry.test/v1/org-context/me');
    expect(new Headers(init?.headers).get('authorization')).toBe(`Bearer ${TOKEN_A}`);
  });

  it('refuses an answer for a different org than the token home org', async () => {
    fetchMock.mockResolvedValue(reply(200, contextB));

    await expect(resolveOrgContext(ORG_A, TOKEN_A)).resolves.toBeNull();
    // Nothing was cached for either org.
    fetchMock.mockResolvedValue(reply(200, contextA));
    await expect(resolveOrgContext(ORG_A, TOKEN_A)).resolves.toEqual(contextA);
    expect(fetchMock).toHaveBeenCalledTimes(2);
  });

  it.each([
    ['a CONCESSION context with an assembly', { ...contextA, scope: 'CONCESSION' }],
    ['an ASSEMBLY context without an assembly', { ...contextA, assemblyId: null }],
    ['an unknown scope', { ...contextA, scope: 'PORTFOLIO' }],
    ['no concession id', { ...contextA, concessionId: '' }],
    ['a non-object body', 'org-a'],
  ])('refuses %s', async (_label, body) => {
    fetchMock.mockResolvedValue(reply(200, body));

    await expect(resolveOrgContext(ORG_A, TOKEN_A)).resolves.toBeNull();
  });

  it('keeps each org in its own cache entry', async () => {
    fetchMock.mockResolvedValueOnce(reply(200, contextA)).mockResolvedValueOnce(reply(200, contextB));

    await expect(resolveOrgContext(ORG_A, TOKEN_A)).resolves.toEqual(contextA);
    await expect(resolveOrgContext(ORG_B, TOKEN_B)).resolves.toEqual(contextB);
    await expect(resolveOrgContext(ORG_A, TOKEN_A)).resolves.toEqual(contextA);
    await expect(resolveOrgContext(ORG_B, TOKEN_B)).resolves.toEqual(contextB);
    expect(fetchMock).toHaveBeenCalledTimes(2);
  });

  it('expires a context after ORG_CONTEXT_TTL_MS, so a removed registry row stops being served', async () => {
    fetchMock.mockResolvedValueOnce(reply(200, contextA)).mockResolvedValueOnce(reply(404, { error: 'not_found' }));

    await resolveOrgContext(ORG_A, TOKEN_A);
    vi.advanceTimersByTime(ORG_CONTEXT_TTL_MS - 1);
    await expect(resolveOrgContext(ORG_A, TOKEN_A)).resolves.toEqual(contextA);
    vi.advanceTimersByTime(2);
    await expect(resolveOrgContext(ORG_A, TOKEN_A)).resolves.toBeNull();
    expect(ORG_CONTEXT_TTL_MS).toBeLessThanOrEqual(60_000);
  });

  it('remembers an unregistered org only briefly', async () => {
    fetchMock.mockResolvedValueOnce(reply(404)).mockResolvedValueOnce(reply(200, contextA));

    await expect(resolveOrgContext(ORG_A, TOKEN_A)).resolves.toBeNull();
    await expect(resolveOrgContext(ORG_A, TOKEN_A)).resolves.toBeNull();
    vi.advanceTimersByTime(ORG_NOT_REGISTERED_TTL_MS + 1);
    await expect(resolveOrgContext(ORG_A, TOKEN_A)).resolves.toEqual(contextA);
    expect(fetchMock).toHaveBeenCalledTimes(2);
  });

  it.each([401, 403, 500, 503])('never caches a %s answer', async (status) => {
    fetchMock.mockResolvedValueOnce(reply(status)).mockResolvedValueOnce(reply(200, contextA));

    await expect(resolveOrgContext(ORG_A, TOKEN_A)).resolves.toBeNull();
    await expect(resolveOrgContext(ORG_A, TOKEN_A)).resolves.toEqual(contextA);
    expect(fetchMock).toHaveBeenCalledTimes(2);
  });

  it('shares one lookup between concurrent callers for the same org', async () => {
    let release!: (response: Response) => void;
    fetchMock.mockReturnValueOnce(new Promise((resolve) => { release = resolve; }));

    const calls = Array.from({ length: 5 }, () => resolveOrgContext(ORG_A, TOKEN_A));
    release(reply(200, contextA));

    await expect(Promise.all(calls)).resolves.toEqual(Array(5).fill(contextA));
    expect(fetchMock).toHaveBeenCalledTimes(1);
  });

  it('does not share a lookup between orgs', async () => {
    fetchMock.mockImplementation(async (_url, init) =>
      reply(200, new Headers(init?.headers).get('authorization') === `Bearer ${TOKEN_A}` ? contextA : contextB));

    const [a, b] = await Promise.all([resolveOrgContext(ORG_A, TOKEN_A), resolveOrgContext(ORG_B, TOKEN_B)]);

    expect(a).toEqual(contextA);
    expect(b).toEqual(contextB);
    expect(fetchMock).toHaveBeenCalledTimes(2);
  });

  it('starts a fresh lookup after a shared one fails', async () => {
    fetchMock.mockResolvedValueOnce(reply(503)).mockResolvedValueOnce(reply(200, contextA));

    await expect(Promise.all([resolveOrgContext(ORG_A, TOKEN_A), resolveOrgContext(ORG_A, TOKEN_A)]))
      .resolves.toEqual([null, null]);
    await expect(resolveOrgContext(ORG_A, TOKEN_A)).resolves.toEqual(contextA);
    expect(fetchMock).toHaveBeenCalledTimes(2);
  });

  it('fails closed on a network error without surfacing the token', async () => {
    fetchMock.mockRejectedValue(new Error(`connect ECONNREFUSED (sent Bearer ${TOKEN_A})`));
    const errors = vi.spyOn(console, 'error').mockImplementation(() => {});

    await expect(resolveOrgContext(ORG_A, TOKEN_A)).resolves.toBeNull();
    expect(errors).not.toHaveBeenCalled();
    errors.mockRestore();
  });
});
